definitions.definition:
/// Every `*.jsonl` file in `dir`, sorted. A missing directory gives an empty list.
pub fn pending_journals(dir: &std::path::Path) -> Vec<std::path::PathBuf>
/// `home/Library/Application Support/KateM5Rust/stash`.
pub fn stash_dir(home: &std::path::Path) -> std::path::PathBuf
/// Write `text` to `dir/untitled-<index>.txt` through a temp file and a rename.
pub fn write_stash(dir: &std::path::Path, index: u32, text: &str) -> std::io::Result<std::path::PathBuf>
/// The stashed texts in index order.
pub fn read_stashes(dir: &std::path::Path) -> std::io::Result<Vec<String>>
/// Remove every stash file.
pub fn clear_stash(dir: &std::path::Path) -> std::io::Result<()>
